// Formulário da fábrica de vídeos grátis.
// ── Moldura das páginas (mesmo visual em todos os fluxos grátis) ──
function pagina(titulo, corpo, script) {
  const css = `
:root{--fundo:#f6f5f2;--cartao:#fff;--texto:#1d1d1b;--suave:#6b6b66;--linha:#e3e1db;--acento:#0f766e;--acento2:#115e59;--erro:#b42318;--ok:#067647}
@media (prefers-color-scheme:dark){:root{--fundo:#121412;--cartao:#1b1e1c;--texto:#ecebe7;--suave:#a3a39d;--linha:#2c302d;--acento:#2dd4bf;--acento2:#5eead4;--erro:#f97066;--ok:#47cd89}}
*{box-sizing:border-box}body{margin:0;background:var(--fundo);color:var(--texto);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
main{max-width:760px;margin:0 auto;padding:20px 16px 48px}h1{font-size:1.45rem;margin:.2em 0 .1em}h2{font-size:1.1rem;margin:1.2em 0 .5em}
.sub{color:var(--suave);margin:0 0 18px}.cartao{background:var(--cartao);border:1px solid var(--linha);border-radius:14px;padding:16px;margin:12px 0}
label{display:block;font-weight:600;margin:12px 0 6px}textarea,input,select{width:100%;padding:11px 12px;border:1px solid var(--linha);border-radius:10px;background:var(--fundo);color:var(--texto);font:inherit}
textarea{min-height:120px;resize:vertical}.linha{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
button,.botao{display:inline-block;background:var(--acento);color:#fff;border:0;border-radius:10px;padding:12px 18px;font:600 1rem system-ui,sans-serif;cursor:pointer;text-decoration:none;margin-top:14px}
@media (prefers-color-scheme:dark){button,.botao{color:#04211e}}
button[disabled]{opacity:.55;cursor:wait}.botao.sec{background:transparent;color:var(--acento);border:1px solid var(--acento)}
.aviso{color:var(--suave);font-size:.9rem}.erro{color:var(--erro);font-weight:600}.ok{color:var(--ok);font-weight:600}
.grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.grade img,.grade video{width:100%;border-radius:10px;border:1px solid var(--linha);background:#000}
video,audio{width:100%;margin-top:10px;border-radius:10px}pre{white-space:pre-wrap;background:var(--fundo);border:1px solid var(--linha);border-radius:10px;padding:12px;font-size:.9rem}
.barra{height:8px;background:var(--linha);border-radius:99px;overflow:hidden;margin:10px 0}.barra i{display:block;height:100%;background:var(--acento);width:0;transition:width .6s}
.selo{display:inline-block;font-size:.78rem;border:1px solid var(--linha);border-radius:99px;padding:2px 9px;color:var(--suave);margin:2px 4px 2px 0}
footer{color:var(--suave);font-size:.82rem;margin-top:28px}`;
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta name="robots" content="noindex"><title>' + titulo + '</title><style>' + css + '</style></head><body><main>' + corpo +
    '<footer>Feito com serviços grátis e sem chave (Hugging Face, Pollinations, Bing/Google Tradutor). Pode demorar ou falhar quando eles estão cheios.</footer>' +
    '</main>' + (script ? '<script>' + script + '</script>' : '') + '</body></html>';
}
const escHtml = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const corpo = `
<h1>🎬 Fábrica de vídeos grátis</h1>
<p class="sub">Você dá o tema; a IA escreve o roteiro, gera as imagens, narra e monta o vídeo. Tudo grátis e sem chave
(Pollinations, Hugging Face e Bing Tradutor). Leva de 2 a 8 minutos.</p>
<div class="cartao">
  <label for="tema">Tema do vídeo</label>
  <textarea id="tema" maxlength="300" style="min-height:80px">3 curiosidades sobre o Sol que quase ninguém sabe</textarea>
  <div class="linha">
    <div><label for="tipo">Tipo</label><select id="tipo">
      <option value="curiosidades">Curiosidades</option><option value="historia">História narrada</option>
      <option value="dicas">Dicas / passo a passo</option><option value="noticia">Explicação de notícia</option>
      <option value="produto">Apresentação de produto/serviço</option></select></div>
    <div><label for="duracao">Duração</label><select id="duracao"><option value="30">~30 s</option>
      <option value="45" selected>~45 s</option><option value="60">~60 s</option></select></div>
    <div><label for="estilo">Estilo das imagens</label><select id="estilo"><option value="foto">Foto realista</option>
      <option value="cinema">Cinema</option><option value="ilustracao">Ilustração</option><option value="anime">Anime</option>
      <option value="3d">3D animação</option></select></div>
  </div>
  <div class="linha">
    <div><label for="voz">Voz</label><select id="voz"><option value="thalita">Thalita</option><option value="andrew">Andrew</option>
      <option value="brian">Brian</option><option value="emma">Emma</option><option value="google">Google (reserva)</option></select></div>
    <div><label for="velocidade">Ritmo</label><select id="velocidade"><option value="0">Normal</option>
      <option value="10" selected>Um pouco rápido</option><option value="20">Rápido (Shorts)</option></select></div>
    <div><label for="modo">Formato</label><select id="modo">
      <option value="navegador">Vertical 9:16 (montado no seu navegador)</option>
      <option value="nuvem">Deitado 16:9 (montado na nuvem, pronto)</option></select></div>
  </div>
  <button id="ir">Criar vídeo</button>
  <p id="estado" class="aviso"></p>
</div>
<div class="cartao aviso"><b>Como sai:</b> deitado 16:9 vem pronto (montador grátis do Hugging Face, 1280x720, legenda
palavra a palavra). Vertical 9:16 é montado no seu navegador na página do resultado (deixe a aba aberta e à vista
durante a montagem). Outros fluxos: <code>POST</code> aqui com <code>{"tema":"...","modo":"nuvem"}</code> → <code>{"link":"..."}</code>.</div>`;
const script = `
const $ = id => document.getElementById(id);
$('ir').onclick = async () => {
  $('ir').disabled = true; $('estado').className = 'aviso'; $('estado').textContent = 'Enviando...';
  try {
    const corpo = {}; for (const k of ['tema', 'tipo', 'duracao', 'estilo', 'voz', 'velocidade', 'modo']) corpo[k] = $(k).value;
    const r = await fetch(location.pathname, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(corpo) });
    const j = await r.json();
    if (!j.ok) throw new Error(j.erro || 'falhou');
    $('estado').className = 'ok'; $('estado').innerHTML = 'Começou! Abrindo o andamento... <a href="' + j.link + '">' + j.link + '</a>';
    location.href = j.link;
  } catch (e) { $('estado').className = 'erro'; $('estado').textContent = 'Não deu: ' + e.message; $('ir').disabled = false; }
};`;
return [{ json: { html: pagina('Fábrica de vídeos grátis', corpo, script) } }];

// Confere o pedido e prepara o trabalho (job). Formato: nuvem = 16:9 pronto; navegador = 9:16 montado na página.
const ent = $input.first().json;
const b = ent.body || {};
const h = ent.headers || {};
const base = (h['x-forwarded-proto'] || 'https') + '://' + (h['x-forwarded-host'] || h.host);
const tema = String(b.tema || '').replace(/\s+/g, ' ').trim().slice(0, 300);
if (tema.length < 3) return [{ json: { ok: false, erro: 'Escreva o tema do vídeo (pelo menos 3 letras).' } }];
const modo = b.modo === 'nuvem' ? 'nuvem' : 'navegador';
const duracao = [30, 45, 60].includes(Number(b.duracao)) ? Number(b.duracao) : 45;
const voz = ['thalita', 'andrew', 'brian', 'emma', 'google'].includes(b.voz) ? b.voz : 'thalita';
const velocidade = Math.max(-20, Math.min(30, Number(b.velocidade ?? 10) || 0));
const TIPOS = {
  curiosidades: 'vídeo de curiosidades: fatos surpreendentes e verdadeiros, um por cena',
  historia: 'história narrada com começo, conflito e desfecho surpreendente',
  dicas: 'dicas práticas ou passo a passo, uma dica por cena',
  noticia: 'explicação simples de um assunto/notícia, sem inventar fatos',
  produto: 'apresentação de produto ou serviço: problema, solução, benefícios e chamada para ação' };
const tipo = TIPOS[b.tipo] ? b.tipo : 'curiosidades';
const ESTILOS = {
  foto: 'photorealistic photo, natural light, high detail', cinema: 'cinematic film still, dramatic lighting, depth of field',
  ilustracao: 'digital illustration, clean shapes, vibrant colors', anime: 'anime style illustration, detailed, vibrant colors',
  '3d': '3D animated movie style, soft lighting, cute' };
const estilo = ESTILOS[b.estilo] ? b.estilo : 'foto';
const job = (Date.now().toString(36) + Math.random().toString(36).slice(2, 6)).toLowerCase();
return [{ json: { ok: true, job, base, tema, modo, formato: modo === 'nuvem' ? '16:9' : '9:16', duracao, voz, velocidade,
  tipo, tipo_txt: TIPOS[tipo], estilo, estilo_img: ESTILOS[estilo],
  link: base + '/webhook/gratis-video-ver?id=' + job, arquivo: base + '/webhook/gratis-video-arquivo?id=' + job + '-',
  chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13) } }];

// Escreve o roteiro com a IA grátis (Pollinations). Uma chamada só: o limite sem chave é 1 resposta a cada 30 s.
// Curiosidades, notícia e dicas vêm ancoradas no texto da Wikipédia (a IA grátis inventa fatos sem isso).
// ── Texto por IA grátis e sem chave (Pollinations, modelo openai-fast) ──
// Limite sem chave: 1 resposta a cada 30 s por IP. Quem chama em sequência precisa esperar (nó ⏳ de 31 s).
// Sem chave o "response_format" dá 400: o JSON é pedido no texto e lido com lerJson (tolera ```json e texto em volta).
// O modelo grátis "pensa" antes de responder: sem reasoning_effort low ele estoura o limite e devolve 400
// (output_token_limit_exceeded); "minimal" não existe e "medium" também estoura.
async function perguntaIA(helpers, mensagens, emJson = false, tentativas = 1) {
  let ultimo = '';
  for (let t = 0; t < tentativas; t++) {
    try {
      const r = await helpers.httpRequest({ method: 'POST', url: 'https://text.pollinations.ai/openai', json: true, timeout: 50000,
        // seed aleatória: sem ela o Pollinations devolve do cache a MESMA resposta para o mesmo pedido
        body: { model: 'openai', messages: mensagens, reasoning_effort: 'low', max_tokens: 6000, seed: Math.floor(Math.random() * 1e9) } });
      const txt = r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
      if (txt) return emJson ? lerJson(txt) : String(txt).trim();
      ultimo = 'resposta vazia';
    } catch (e) {
      ultimo = String((e.response && e.response.body && JSON.stringify(e.response.body)) || e.message || e).slice(0, 200);
    }
  }
  throw new Error('IA grátis (Pollinations) não respondeu: ' + ultimo);
}

function lerJson(txt) {
  const s = String(txt).replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try { return JSON.parse(s); } catch (e) { /* tenta achar o bloco */ }
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i >= 0 && j > i) return JSON.parse(s.slice(i, j + 1));
  throw new Error('a IA não devolveu JSON');
}

// ── Fatos de verdade, grátis e sem chave: API pública da Wikipédia em português ──
// A IA grátis inventa números e fatos; com o texto da Wikipédia no pedido ela só usa o que está lá.
async function fatosWikipedia(helpers, tema) {
  const PARE = /\b(curiosidades?|sobre|que|quase|ningu[eé]m|sabe|sabia|voc[eê]|os|as|o|a|um|uma|de|do|da|dos|das|e|em|no|na|nos|nas|para|por|com|fatos?|incr[ií]veis|segredos?|coisas?|explica[cç][aã]o|not[ií]cia|dicas?|como|porque|por que|\d+)\b/gi;
  const busca = tema.replace(PARE, ' ').replace(/[^\p{L}\p{N} -]/gu, ' ').replace(/\s+/g, ' ').trim() || tema;
  const cab = { 'User-Agent': 'n8n-fluxos-gratis/1.0 (biblioteca de fluxos sem chave)' };
  const s = await helpers.httpRequest({ json: true, timeout: 15000, headers: cab,
    url: 'https://pt.wikipedia.org/w/api.php?action=query&list=search&format=json&srlimit=1&srsearch=' + encodeURIComponent(busca) });
  const titulo = (((s || {}).query || {}).search || []).map(x => x.title)[0];
  if (!titulo) return { fonte: '', texto: '' };
  const e = await helpers.httpRequest({ json: true, timeout: 15000, headers: cab,
    url: 'https://pt.wikipedia.org/w/api.php?action=query&prop=extracts&explaintext=1&exsectionformat=plain&format=json&exchars=3500&titles=' +
      encodeURIComponent(titulo) });
  const pag = Object.values(((e || {}).query || {}).pages || {})[0] || {};
  const texto = String(pag.extract || '').replace(/\n{2,}/g, '\n').trim().slice(0, 3500);
  return { fonte: texto ? 'Wikipédia: ' + titulo : '', texto };
}

const v = $('🧩 Confere o pedido').first().json;
const nCenas = Math.max(5, Math.min(10, Math.round(v.duracao / 6)));
const palavras = Math.round(v.duracao * 2.5);
let ref = { fonte: '', texto: '' };
if (['curiosidades', 'noticia', 'dicas'].includes(v.tipo)) {
  try { ref = await fatosWikipedia(this.helpers, v.tema); } catch (e) { ref = { fonte: '', texto: '' }; }
}
const sistema = `Você é roteirista de vídeos curtos em português do Brasil para YouTube Shorts, Reels e TikTok.
Responda SOMENTE um JSON válido, sem markdown, neste formato:
{"titulo":"","descricao":"","hashtags":["#..."],"cenas":[{"fala":"","imagem":""}]}
Regras:
- Exatamente ${nCenas} cenas. A 1ª fala é o GANCHO: prende nos primeiros 3 segundos (pergunta ou fato surpreendente VERDADEIRO).
- "fala": o que o narrador diz na cena, 8 a 22 palavras, frase natural para ouvir, com acentos, sem emojis, sem listas,
  sem parênteses. Somando todas as falas, cerca de ${palavras} palavras. A última fala fecha a ideia e convida a seguir para
  mais vídeos, sem citar nome de canal.
- "imagem": descrição EM INGLÊS da imagem da cena (máx. 45 palavras), mostrando exatamente o assunto da fala, composição
  ${v.formato === '9:16' ? 'vertical (portrait)' : 'horizontal (landscape)'}, estilo: ${v.estilo_img}. Sem texto, letras,
  números escritos, logotipos ou marcas d'água na imagem. Sem pessoas famosas reais. Mesmos personagens com a mesma aparência
  em todas as cenas quando houver personagem. A imagem da última cena também mostra o assunto do vídeo (nada de pessoa
  posando, colagem ou grade de fotos).
- ${ref.texto ? 'Use SOMENTE fatos que estão no TEXTO DE REFERÊNCIA. Não invente números nem fatos fora dele.'
    : 'Fatos verdadeiros e conferíveis. Se não tiver certeza de um número, não use número.'}
- Nada de frase sem sentido ou exagero falso.
- "titulo": até 90 caracteres, 2 a 4 palavras-chave em MAIÚSCULAS, no máximo 1 emoji, desperta curiosidade, sem "#shorts".
- "descricao": 2 ou 3 frases sobre o vídeo e uma pergunta para o público comentar.
- "hashtags": 3 a 6 hashtags específicas do assunto (nada genérico como #shorts #viral #ia #fyp).`;
const pedido = `Tema: ${v.tema}\nTipo: ${v.tipo_txt}\nDuração alvo: ${v.duracao} segundos.` +
  (ref.texto ? `\n\nTEXTO DE REFERÊNCIA (${ref.fonte}):\n${ref.texto}` : '');
try {
  const r = await perguntaIA(this.helpers, [{ role: 'system', content: sistema }, { role: 'user', content: pedido }], true);
  const cenas = (Array.isArray(r.cenas) ? r.cenas : [])
    .map(c => ({ fala: String(c.fala || '').replace(/\s+/g, ' ').trim(), imagem: String(c.imagem || '').replace(/\s+/g, ' ').trim() }))
    .filter(c => c.fala.length > 3);
  if (cenas.length < 3) throw new Error('roteiro veio com poucas cenas');
  for (const c of cenas) if (!c.imagem) c.imagem = v.tema + ', ' + v.estilo_img;
  return [{ json: { ok: true, titulo: String(r.titulo || v.tema).slice(0, 100), descricao: String(r.descricao || '').slice(0, 900),
    hashtags: limpaHashtags(r.hashtags), cenas: cenas.slice(0, 12), fonte: ref.fonte, referencia: ref.texto } }];
} catch (e) {
  return [{ json: { ok: false, erro: String(e.message || e).slice(0, 250), fonte: ref.fonte, referencia: ref.texto } }];
}

function limpaHashtags(h) {
  return (Array.isArray(h) ? h : String(h || '').split(/\s+/))
    .map(t => '#' + String(t).replace(/^#+/, '').replace(/[^\p{L}\p{N}_]/gu, '')).filter(t => t.length > 2)
    .filter(t => !/^#(shorts|viral|ia|fyp|foryou|parati)$/i.test(t)).slice(0, 6);
}

// Escreve o roteiro com a IA grátis (Pollinations). Uma chamada só: o limite sem chave é 1 resposta a cada 30 s.
// Curiosidades, notícia e dicas vêm ancoradas no texto da Wikipédia (a IA grátis inventa fatos sem isso).
// ── Texto por IA grátis e sem chave (Pollinations, modelo openai-fast) ──
// Limite sem chave: 1 resposta a cada 30 s por IP. Quem chama em sequência precisa esperar (nó ⏳ de 31 s).
// Sem chave o "response_format" dá 400: o JSON é pedido no texto e lido com lerJson (tolera ```json e texto em volta).
// O modelo grátis "pensa" antes de responder: sem reasoning_effort low ele estoura o limite e devolve 400
// (output_token_limit_exceeded); "minimal" não existe e "medium" também estoura.
async function perguntaIA(helpers, mensagens, emJson = false, tentativas = 1) {
  let ultimo = '';
  for (let t = 0; t < tentativas; t++) {
    try {
      const r = await helpers.httpRequest({ method: 'POST', url: 'https://text.pollinations.ai/openai', json: true, timeout: 50000,
        // seed aleatória: sem ela o Pollinations devolve do cache a MESMA resposta para o mesmo pedido
        body: { model: 'openai', messages: mensagens, reasoning_effort: 'low', max_tokens: 6000, seed: Math.floor(Math.random() * 1e9) } });
      const txt = r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
      if (txt) return emJson ? lerJson(txt) : String(txt).trim();
      ultimo = 'resposta vazia';
    } catch (e) {
      ultimo = String((e.response && e.response.body && JSON.stringify(e.response.body)) || e.message || e).slice(0, 200);
    }
  }
  throw new Error('IA grátis (Pollinations) não respondeu: ' + ultimo);
}

