// Junta os caminhos dos arquivos já enviados ao montador grátis (Space Tim13ekd/video-ffmpeg, 1280x720) e monta o pedido.
// O Space divide as palavras IGUALMENTE entre as imagens e escreve cada trecho numa linha só: com 6 imagens e 80
// palavras a legenda estourava a tela. Por isso cada imagem entra repetida (mesmo arquivo, sem novo envio) em trechos
// de ~4 palavras, na proporção das palavras de cada cena.
// ── Spaces do Hugging Face pela API pública do Gradio (sem chave; cota grátis por IP) ──
// Chamada curta (cabe nos 60 s do Code). Para espera longa, use dois nós HTTP: POST .../call/<rota> e
// GET .../call/<rota>/<event_id> (texto), e depois gradioLe() num Code.
async function gradioChama(helpers, espaco, rota, dados, limite = 50000) {
  const base = 'https://' + espaco + '.hf.space/gradio_api/call/' + rota;
  const r = await helpers.httpRequest({ method: 'POST', url: base, body: { data: dados }, json: true, timeout: 20000 });
  const ev = r && r.event_id;
  if (!ev) throw new Error(espaco + ': sem event_id');
  return gradioLe(String(await helpers.httpRequest({ url: base + '/' + ev, timeout: limite, json: false })), espaco);
}

// Lê a resposta (SSE) da 2ª chamada: devolve o JSON final ou dá erro com o motivo.
function gradioLe(txt, espaco = 'Hugging Face') {
  txt = String(txt || '');
  if (!txt.includes('event: complete')) {
    const m = /event: error\s*\ndata: (.*)/.exec(txt);
    const motivo = m && m[1] !== 'null' ? m[1].slice(0, 200) : 'recusou (a cota grátis do Hugging Face acabou ou a fila está cheia; tente mais tarde)';
    throw new Error(espaco + ': ' + motivo);
  }
  const linhas = txt.split('\n').filter(l => l.startsWith('data:'));
  return JSON.parse(linhas[linhas.length - 1].slice(5));
}

const urlDe = d => { const m = /"url":\s*"([^"]+)"/.exec(JSON.stringify(d)); return m ? m[1] : null; };

// Arquivos para o Space: o Gradio não aceita link de fora nem base64 nas entradas de arquivo, só o caminho de um
// upload (POST .../gradio_api/upload, multipart). O upload tem que ser pelo nó HTTP do n8n (n8nlib.http_envia_arquivo):
// o httpRequest do Code manda o binário como UTF-8 e estraga o arquivo (testado 30/10: 512 bytes viraram 768).
const arquivoGradio = (caminho, nome) => ({ path: caminho, orig_name: nome, meta: { _type: 'gradio.FileData' } });
function caminhoDoUpload(txt) {
  try { const l = JSON.parse(String(txt || '')); return Array.isArray(l) && l[0] ? l[0] : null; } catch (e) { return null; }
}

const ESPACO = 'tim13ekd-video-ffmpeg';
const voz = $('🎙️ Narra o roteiro').first().json;
const itens = $('🧩 Prepara os arquivos').all().map(i => i.json);
const respostas = $input.all().map(i => i.json);
try {
  const caminhos = itens.map((it, k) => ({ ...it, caminho: caminhoDoUpload(respostas[k] && respostas[k].data) }));
  const falhou = caminhos.filter(c => !c.caminho);
  if (falhou.length) throw new Error('o envio de ' + falhou.length + ' arquivo(s) ao montador falhou: ' +
    String((respostas.find(r => !caminhoDoUpload(r.data)) || {}).data || (respostas[0] || {}).error || '').slice(0, 120));
  const porCena = Object.fromEntries(caminhos.filter(c => c.tipo === 'img').map(c => [c.n, arquivoGradio(c.caminho, c.nome)]));
  const audio = caminhos.find(c => c.tipo === 'voz');
  const palavrasCena = voz.cenas.map(c => c.fala.split(/\s+/).filter(Boolean).length);
  const total = palavrasCena.reduce((a, b) => a + b, 0);
  const N = Math.max(voz.cenas.length, Math.ceil(total / 4.5));
  const quantas = palavrasCena.map(w => Math.max(1, Math.round(w * N / total)));
  const imagens = [];
  voz.cenas.forEach((c, i) => { for (let k = 0; k < quantas[i]; k++) imagens.push(porCena[c.n] || Object.values(porCena)[0]); });
  const dados = [imagens, voz.texto, Math.round(voz.segundos / total * 1000) / 1000,
    Math.round(voz.segundos / imagens.length * 1000) / 1000, 0.12, 50, 0.86, arquivoGradio(audio.caminho, 'voz.mp3'),
    'Highlight', 'DejaVu Sans Bold'];
  return [{ json: { ok: true, trechos: imagens.length, url_chamada: 'https://' + ESPACO + '.hf.space/gradio_api/call/generate_slideshow_with_audio',
    corpo: { data: dados } } }];
} catch (e) {
  return [{ json: { ok: false, erro: String(e.message || e).slice(0, 220) } }];
}

// Lê a resposta do montador e baixa o MP4 pronto.
// ── Spaces do Hugging Face pela API pública do Gradio (sem chave; cota grátis por IP) ──
// Chamada curta (cabe nos 60 s do Code). Para espera longa, use dois nós HTTP: POST .../call/<rota> e
// GET .../call/<rota>/<event_id> (texto), e depois gradioLe() num Code.
async function gradioChama(helpers, espaco, rota, dados, limite = 50000) {
  const base = 'https://' + espaco + '.hf.space/gradio_api/call/' + rota;
  const r = await helpers.httpRequest({ method: 'POST', url: base, body: { data: dados }, json: true, timeout: 20000 });
  const ev = r && r.event_id;
  if (!ev) throw new Error(espaco + ': sem event_id');
  return gradioLe(String(await helpers.httpRequest({ url: base + '/' + ev, timeout: limite, json: false })), espaco);
}

// Lê a resposta (SSE) da 2ª chamada: devolve o JSON final ou dá erro com o motivo.
function gradioLe(txt, espaco = 'Hugging Face') {
  txt = String(txt || '');
  if (!txt.includes('event: complete')) {
    const m = /event: error\s*\ndata: (.*)/.exec(txt);
    const motivo = m && m[1] !== 'null' ? m[1].slice(0, 200) : 'recusou (a cota grátis do Hugging Face acabou ou a fila está cheia; tente mais tarde)';
    throw new Error(espaco + ': ' + motivo);
  }
  const linhas = txt.split('\n').filter(l => l.startsWith('data:'));
  return JSON.parse(linhas[linhas.length - 1].slice(5));
}

const urlDe = d => { const m = /"url":\s*"([^"]+)"/.exec(JSON.stringify(d)); return m ? m[1] : null; };

// Arquivos para o Space: o Gradio não aceita link de fora nem base64 nas entradas de arquivo, só o caminho de um
// upload (POST .../gradio_api/upload, multipart). O upload tem que ser pelo nó HTTP do n8n (n8nlib.http_envia_arquivo):
// o httpRequest do Code manda o binário como UTF-8 e estraga o arquivo (testado 30/10: 512 bytes viraram 768).
const arquivoGradio = (caminho, nome) => ({ path: caminho, orig_name: nome, meta: { _type: 'gradio.FileData' } });
function caminhoDoUpload(txt) {
  try { const l = JSON.parse(String(txt || '')); return Array.isArray(l) && l[0] ? l[0] : null; } catch (e) { return null; }
}

const ev = $('🌐 Pede a montagem').first().json;
try {
  if (!ev || !ev.event_id) throw new Error('o montador não aceitou o pedido (' + JSON.stringify(ev).slice(0, 120) + ')');
  const d = gradioLe($input.first().json.data, 'montador');
  const url = urlDe(d);
  if (!url) throw new Error('o montador respondeu sem vídeo: ' + JSON.stringify(d).slice(0, 150));
  const mp4 = Buffer.from(await this.helpers.httpRequest({ url, encoding: 'arraybuffer', timeout: 50000 }));
  if (mp4.length < 20000) throw new Error('vídeo vazio');
  return [{ json: { ok: true, b64: mp4.toString('base64'), bytes: mp4.length } }];
} catch (e) {
  return [{ json: { ok: false, erro: String(e.message || e).slice(0, 250) } }];
}

