}
const escHtml = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const q = $input.first().json.query || {};
const job = String(q.id || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 40);
const corpo = `
